import{_ as s,l as i,o as t,c as n,v as e,p as l,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"抽象解释","description":"","frontmatter":{"title":"抽象解释","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/abstract-interpretation.md","filePath":"cs/abstract-interpretation.md","lastUpdated":1789023840000}'),h={name:"cs/abstract-interpretation.md"};function u(_,a,m,f,E,A){const o=i("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="抽象解释" tabindex="-1">抽象解释 <a class="header-anchor" href="#抽象解释" aria-label="Permalink to &quot;抽象解释&quot;">​</a></h1><div class="epigraph"><p>在抽象域上模拟程序：具体状态集被 Galois 连接压成格上的元素。不动点给出不变量，服务于类型之外的静态分析。</p><footer>—— 据 Cousot and Cousot, Abstract Interpretation, 1977；龙书数据流章对照；[Knaster–Tarski](/cs/knaster-tarski-fixpoint) 整理</footer></div><p>上一课<a href="/cs/denotational-semantics">指称</a>给出理想含义，太大算不了。缺口是<strong>可靠近似</strong>：区间、符号、符号执行的亲戚——抽象解释。主干<a href="/cs/dataflow-liveness">数据流</a>是同一家族的方程；本课钉 Galois 连接与加宽，不把所有抽象域列成百科。类型系统是一种抽象（类型是抽象值），但本课面向分析器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>具体收集语义：每个程序点的可达状态集。无限。抽象：区间 \\([L,H]\\)、符号、八边形。Galois：\\((\\alpha,\\gamma)\\) 保证抽象转移 \\(\\nabla\\) 可靠（不漏具体行为）。缺口是<strong>可靠与精度的权衡</strong>，不是 SOS 的一步规则。</p><p>加宽（widening）强迫升链收敛，可能损失精度；变窄再收回一点。循环必须处理——后课自然循环识别与此衔接。</p><h3 id="可靠不是完备" tabindex="-1">可靠不是完备 <a class="header-anchor" href="#可靠不是完备" aria-label="Permalink to &quot;可靠不是完备&quot;">​</a></h3><p>分析可说「可能别名」而其实没有——假阳性。完备相对选定抽象域：域表达不了的性质永远未知。不要把「未报错」当程序无错（若目标是找 bug，漏报更危险，方向会调）。</p><p><span class="marginnote">Cousot–Cousot 1977（POPL）。龙书把到达定值、可用表达式写成数据流，是有限高度格上的抽象解释特例。本课不写 Astrée 的全部域。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选抽象域与转移。解 \\(X=F(X)\\) 用迭代+加宽。用于：值范围、空指针、常量（后课常量传播是平坦域）。类型推导也可看成抽象：合一是精确的，子类型是近似方向。</p>',11)),(t(),l(c,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CON%5B%22%E5%85%B7%E4%BD%93%E7%8A%B6%E6%80%81%E9%9B%86%22%5D%20--%3E%20A%5B%22%CE%B1%20%E6%8A%BD%E8%B1%A1%22%5D%0A%20%20A%20--%3E%20FIX%5B%22%E6%A0%BC%E4%B8%8A%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20FIX%20--%3E%20G%5B%22%CE%B3%20%E5%85%B7%E4%BD%93%E5%8C%96%20%E2%8A%82%20%E5%8F%AF%E9%9D%A0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与效应、区域：可当抽象域的分量。与 SMT：抽象解释给不变量，SMT 可在路径上精化，<a href="/cs/smt-solver">SMT</a> 已见。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Galois 连接保证可靠；若不要求连接，至少要 sound transformer（over-approx）。并行与弱内存使具体语义本身难写，分析更保守。</p><p>不要用抽象解释替代线性/借用：后者是语言纪律，前者是对已写程序的近似。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现完整区间分析器。后课默认：数据流优化是有限格上的 AI。下一课空与 Option：把「可能空」从分析变成类型。</p><p>也不把机器学习当抽象域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>抽象解释：Galois + 格不动点，可靠近似收集语义。</li><li>数据流是特例；加宽服务循环。</li><li>可靠≠完备；假阳性与漏报取决于问题方向。</li><li>出处：Cousot and Cousot, 1977；对照龙书数据流；Knaster–Tarski。</li></ul>',9))])}const T=s(h,[["render",u]]);export{B as __pageData,T as default};
